-- Supplier groups + suppliers imported from document/mim data/Anis/smart_pur_suppliers_list.pdf
CREATE TABLE supplier_group (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code        VARCHAR(30)  NOT NULL UNIQUE,
    name        VARCHAR(160) NOT NULL,
    name_bn     VARCHAR(200),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

ALTER TABLE supplier ADD COLUMN group_id UUID REFERENCES supplier_group(id);
CREATE INDEX idx_supplier_group ON supplier(group_id);


